import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, SessionRateLimit } from 'claude-code'

import type { RangeCheck, RangeDay, RangeReading, RangeSettings, RangeStep, RangeSync, RangeWatch } from '../types'
import {
  DEFAULT_SETTINGS, KEEP, MIN, heartbeat, MIN_RECORDED_H, UNIT_MAX, UNIT_MIN, averageName, clampWindow, averageNote, chosenAverage,
  drawingHeight, emptyChartSvg, emptyChartText, fit, fiveChart, LAST_INFO, LAST_LABEL, lastIsShort, lastWindow, lastWindowNote, lastWindowText, merge, parseWindow, project, rateText, recordedHours, resetsIn,
  C, dur, HOUR, isShort, leftText, paceText, rangeTrack, rateShort, refine, runsOut, weekChart, windowHours, isStale, ofKind, DAY,
} from './range'
import type { Average, LastWindow, Model, TrackSeg, TrackTone } from './range'
import { DEFAULT_PALETTES, historyPalettes, palettesFor, resolveTheme } from './theme'
import { dailyTotals, selfCheck, typicalMiss, weekPlan } from './pace'
import type { WeekPlan } from './pace'
import {
  cutOff, DAYS_MIN, dayEndText, daysHeight, overBudgetAt, dayName, daysText, dayTime, hm, fiveCardSvg, fiveHead, fivePart, mastheadSvg, oldFigures, one, partsWidth, pastDays,
  showsToday, toCome, todaySvg, todayText, weekBarLabels, weekCardSvg, weekHead, weekHeadline, weekLegendSvg, weekPart,
} from './cards'
import type { Run } from './ui'
import { baselineOf, costRows, learn, mergeSteps, MODELS_INFO, modelsHead, modelsUsage, shortNames, shownEffort, splitText, units, usageSplit } from './models'
import type { UsageSplit } from './models'
import {
  agoText, cancelSignIn, cleanName, configureSync, DEVICE_KEY, DEVICES_FRESH, deleteSynced, deviceLabel, downloadedFor, endSync, GENERIC_NAMES, isDeviceId,
  NAME_KEY, platformOf, refreshDevices, removeDevice, signIn, signOut, startSync, syncTick,
} from './sync'
import type { Lists, Platform, SyncIO } from './sync'

const PANE = 'token-range-monitor'
/** The mod's version, shown in the pane's title: keep it in step with `.claude-plugin/plugin.json`. */
const VERSION = '1.4.8'
const TITLE = `Token Range Monitor ${VERSION}`
const readings = atom({ plugin: 'token-range-monitor', key: 'readings' } as const, [])
const settings = atom({ plugin: 'token-range-monitor', key: 'settings' } as const, DEFAULT_SETTINGS)
const tick = atom({ plugin: 'token-range-monitor', key: 'tick' } as const, 0)
const seen = atom({ plugin: 'token-range-monitor', key: 'seen' } as const, [])
const palettes = atom({ plugin: 'token-range-monitor', key: 'palettes' } as const, DEFAULT_PALETTES)
const steps = atom({ plugin: 'token-range-monitor', key: 'steps' } as const, [])
/** Each whole day's use, kept 8 weeks, and the weekly projection's self-check (see ./pace). */
const days = atom({ plugin: 'token-range-monitor', key: 'days' } as const, [] as RangeDay[])
const check = atom({ plugin: 'token-range-monitor', key: 'check' } as const, [] as RangeCheck[])
/**
 * How much larger the drawings are shown than they're laid out: 1, so their type is the design's own sizes
 * (28, 16 and 13 px) at the card's width.
 */
const ZOOM = 1
/** The strip under a card, and what its Details opens: a shade darker than the card, whatever colour the app gives it. */
const INSET = '#00000017'
/**
 * A drawing as a plain image: the drawings are made for a frame (a wide canvas, filled to the frame's width), so as
 * an image each gets a viewBox the width it was laid out for, `layout`, shown ZOOM times larger; it scales evenly to
 * whatever width it's shown at.
 */
const asImage = (svg: string, layout: number) =>
  svg.replace(/^<svg ([^>]*?)width="\d+" height="(\d+)">/, (_, attrs: string, h: string) =>
    `<svg ${attrs}width="${Math.round(layout * ZOOM)}" height="${Math.round(Number(h) * ZOOM)}" viewBox="0 0 ${Math.round(layout)} ${h}" preserveAspectRatio="xMidYMin meet">`)
/**
 * The desktop's sizes for fitting the cards to the pane, measured in the app: a row of the pane's reported
 * `bodyRows` in px, a row of the cards' own padding, margins and gaps in px (drawn smaller than a text row), and
 * px kept spare under the cards so a small miss in the estimate doesn't scroll.
 */
const FIT_PX = { row: 21, native: 13, spare: 8 }
/** Which cards' Details blocks are open: `week`, `five`, `models`. */
const details = atom({ plugin: 'token-range-monitor', key: 'details' } as const, [] as string[])
/** What the pane's sync row shows; sync itself (./sync) keeps it through syncIO. */
const syncView = atom({ plugin: 'token-range-monitor', key: 'sync' } as const, { status: 'signedOut' } as RangeSync)

/**
 * Usage limits are the account's, so the record is too: everything is stored
 * under the signed-in account (`<account>/`), and signing in to another
 * account starts from that account's own record. Within it each session
 * writes its readings under its own key (`r:`), and the spans it was watching
 * under the twin key (`w:`), so sessions never overwrite each other, and every
 * session reads them all. The responses it saw, each one's model and tokens,
 * go under a third (`u:`).
 */
let account = ''
const OWN = 'r:'
const SEEN = 'w:'
const STEPS = 'u:'
const ownPrefix = () => `${account}/${OWN}`
const seenKeyOf = (key: string) => key.replace(`/${OWN}`, `/${SEEN}`)
const stepsKeyOf = (key: string) => key.replace(`/${OWN}`, `/${STEPS}`)
const newOwnKey = (now: number) => `${ownPrefix()}${now.toString(36)}-${Math.floor(Math.random() * 1e6).toString(36)}`
/** A stored list's key: whose (none for a record kept before accounts), and which kind. */
const parseKey = (key: string) => /^(?:(.+)\/)?([rwu]):/.exec(key)

let ownKey = ''
let own: RangeReading[] = []
let ownSeen: RangeWatch[] = []
let othersSeen: RangeWatch[] = []
let ownSteps: RangeStep[] = []
let othersSteps: RangeStep[] = []

/** The home folder: HOME, or on Windows, where the desktop app often leaves HOME unset, USERPROFILE. */
async function homeOf($: EngineInterface): Promise<string> {
  return (await $.env.get('HOME')) || (await $.env.get('USERPROFILE')) || ''
}

/**
 * The signed-in account and organisation, from Claude Code's own config:
 * the limits belong to both. `none` off a subscription, which has no limits.
 */
let accountRead: { mtime: number; account: string } | undefined
async function accountOf($: EngineInterface): Promise<string | null> {
  try {
    const dir = await $.env.get('CLAUDE_CONFIG_DIR')
    const file = dir ? `${dir}/.claude.json` : `${await homeOf($)}/.claude.json`
    // the file is read again only once it changed
    const { mtimeMs } = await $.fs.stat(file)
    if (accountRead?.mtime === mtimeMs) return accountRead.account
    const o = (JSON.parse(await $.fs.read(file)) as { oauthAccount?: { accountUuid?: string; organizationUuid?: string } }).oauthAccount
    const a = o?.accountUuid ? `${o.accountUuid}.${o.organizationUuid ?? ''}` : 'none'
    accountRead = { mtime: mtimeMs, account: a }
    return a
  } catch {
    // unreadable (mid-write, say): no answer, which is no sign-in elsewhere
    return null
  }
}

/** Follows a sign-in to another account: this session starts a fresh list under it. True when it moved. */
async function followAccount($: EngineInterface): Promise<boolean> {
  const now = await $.clock.now()
  const a = (await accountOf($)) ?? (account || 'none')
  if (a === account) return false
  account = a
  ownKey = newOwnKey(now)
  own = []
  ownSeen = []
  ownSteps = []
  return true
}

/**
 * Claude Code keeps a store per copy of a plugin: one installed from the
 * marketplace and one run from a folder don't share. Every copy's store sits
 * in the same folder, so each copy also reads the others' (never writes them),
 * and sessions running different copies still see each other's usage.
 */
async function otherCopies($: EngineInterface): Promise<Array<[string, unknown]>> {
  try {
    const dir = (await $.env.get('CLAUDE_CONFIG_DIR')) ?? `${await homeOf($)}/.claude`
    const stores = `${dir}/plugins/store`
    const out: Array<[string, unknown]> = []
    for (const f of await $.fs.list(stores)) {
      if (!/^token-range-monitor_.*\.json$/.test(f.name)) continue
      // a file being written as it's read is skipped this time, the others still count
      try {
        out.push(...Object.entries(JSON.parse(await $.fs.read(`${stores}/${f.name}`)) as Record<string, unknown>))
      } catch { /* next minute */ }
    }
    return out
  } catch {
    return []
  }
}

/**
 * Every list recorded on this computer for the signed-in account: this
 * session's, the other sessions', the other copies'. Lists other devices
 * synced are not among them (they are kept under `sync:` keys).
 */
async function localLists($: EngineInterface, now: number) {
  const lists: RangeReading[][] = [own]
  const spans: RangeWatch[] = []
  const stepLists: RangeStep[][] = []
  // the other copies' lists, read as they stand; this copy's own file is among them, and merging drops the repeats
  for (const [key, value] of await otherCopies($)) {
    const k = parseKey(key)
    // a record kept under none was this account's too (see below)
    if (!k || !Array.isArray(value) || (k[1] !== undefined && k[1] !== account && !(k[1] === 'none' && account !== 'none'))) continue
    if (k[2] === 'w') spans.push(...(value as RangeWatch[]))
    else if (k[2] === 'u') stepLists.push(value as RangeStep[])
    else lists.push(value as RangeReading[])
  }
  for (const key of await $.store.keys()) {
    const k = parseKey(key)
    if (!k || key === ownKey || key === seenKeyOf(ownKey) || key === stepsKeyOf(ownKey)) continue
    const [, whose, kind] = k
    const list = ((await $.store.get(key)) ?? []) as Array<RangeReading | RangeWatch | RangeStep>
    // drop lists once everything in them has aged out, whichever account's
    const end = (x: RangeReading | RangeWatch | RangeStep) => (kind === 'w' ? (x as RangeWatch)[1] : x[0])
    if (list.every(x => end(x) < now - KEEP)) { await $.store.delete(key); continue }
    if (whose === undefined) {
      // a record kept before accounts: it was this account's, so it moves under it
      await $.store.set(`${account}/${key}`, list)
      await $.store.delete(key)
    } else if (whose === 'none' && account && account !== 'none') {
      // kept while the account couldn't be read (HOME unset, as on Windows): only a subscription reports
      // limits, so the record was this account's all along, and it moves under it
      await $.store.set(`${account}/${key.slice('none/'.length)}`, list)
      await $.store.delete(key)
    } else if (whose !== account) continue
    if (kind === 'w') spans.push(...(list as RangeWatch[]))
    else if (kind === 'u') stepLists.push(list as RangeStep[])
    else lists.push(list as RangeReading[])
  }
  return { lists, spans, stepLists }
}

/** What this computer recorded, this session's unsaved part included: what sync uploads. */
async function collectLocal($: EngineInterface): Promise<Lists> {
  const { lists, spans, stepLists } = await localLists($, await $.clock.now())
  return { readings: lists, spans: [...spans, ...ownSeen], steps: [...stepLists, ownSteps] }
}

/** A device id another copy's store already holds, so every copy on this computer syncs as one device. */
async function peekDevice($: EngineInterface): Promise<string | undefined> {
  for (const [key, value] of await otherCopies($)) if (key === DEVICE_KEY && isDeviceId(value)) return value
  return undefined
}

/**
 * The computer's own name, for the server's device list: the environment's
 * (COMPUTERNAME on Windows, HOSTNAME where the shell exports it), else a host
 * command's where one can run (`scutil --get ComputerName` on macOS, `hostname`
 * elsewhere; CLI only, kept in the store for sessions that can't run one),
 * else a generic name for the platform ("Mac", "Windows PC", "Linux computer").
 */
async function hostName($: EngineInterface): Promise<string> {
  const fromEnv = cleanName(await $.env.get('COMPUTERNAME').catch(() => undefined)) ?? cleanName(await $.env.get('HOSTNAME').catch(() => undefined))
  if (fromEnv) return fromEnv
  const platform = platformOf({
    os: await $.env.get('OS').catch(() => undefined),
    cfEncoding: await $.env.get('__CF_USER_TEXT_ENCODING').catch(() => undefined),
    home: await $.env.get('HOME').catch(() => undefined),
  })
  const found = await commandName($, platform)
  if (found) {
    await $.store.set(NAME_KEY, found).catch(() => undefined)
    return found
  }
  return cleanName(await $.store.get(NAME_KEY).catch(() => undefined)) ?? GENERIC_NAMES[platform]
}

/** The name a host command prints, or null: no command runs here (the desktop), it failed, or it took over 3 s. */
async function commandName($: EngineInterface, platform: Platform): Promise<string | null> {
  if (platform === 'windows') return null
  try {
    const r = await $.process.run(platform === 'mac' ? ['scutil', '--get', 'ComputerName'] : ['hostname'], { timeoutMs: 3_000 })
    return r.exitCode === 0 ? cleanName(r.stdout.split('\n')[0]) : null
  } catch {
    return null
  }
}

/** The sync pane's own: what sync is doing, sign out, delete, and the linked devices, each removable. */
const SYNC_PANE = 'token-range-monitor-sync'
const SYNC_TITLE = 'Sync settings'

/** Opens the sync settings, and asks for the device list if it wasn't asked for just now. */
async function openSyncPane($: EngineInterface) {
  await $.ui.open({ id: SYNC_PANE, title: SYNC_TITLE })
  void refreshDevices(syncIO($), DEVICES_FRESH).catch(() => undefined)
}

type Els = ReturnType<EngineInterface['ui']['resolve']>

/** Every sync control: the settings pane draws it, and the main pane while a sign-in waits. */
function syncPanel($: EngineInterface, els: Els, v: RangeSync, clockNow: number) {
  const { Box, Text, Button, Link } = els
    return (
      <Box key="sync" flexDirection="column" gap={1} marginTop={1}>
        {/* the row's parts as one flat list: a fragment here is drawn as a column of its own on the desktop */}
        <Box flexDirection="row" flexWrap="wrap" alignItems="center" columnGap={1} rowGap={1}>
          {v.status === 'signedIn'
            ? [
                <Text key="who" color="inactive">{`Synced as ${v.email || 'you'} · last sync ${agoText(v.last, clockNow)} ·`}</Text>,
                <Button key="sync-signout" label="Sign out" dimColor={!!v.busy} onPress={() => void signOut(syncIO($))} />,
                <Button key="sync-delete" label={v.confirmDelete ? 'Press again to delete all synced data' : 'Delete synced data'}
                  variant={v.confirmDelete ? 'primary' : 'secondary'} dimColor={!!v.busy} onPress={() => void deleteSynced(syncIO($))} />,
              ]
            : v.status === 'waiting'
              ? [
                  <Text key="waiting" color="inactive">{`Waiting for sign-in… code ${v.code ?? ''} ·`}</Text>,
                  <Button key="sync-cancel" label="Cancel" onPress={() => void cancelSignIn(syncIO($))} />,
                ]
              : [
                  <Text key="title" color="inactive">{v.status === 'off' ? 'Sync across devices · off' : 'Sync across devices ·'}</Text>,
                  ...(v.status === 'off' ? [] : [<Button key="sync-signin" label="Sign in" dimColor={!!v.busy} onPress={() => void signIn(syncIO($))} />]),
                ]}
        </Box>
        {/* the devices signed in to this account, this one first: any other one can be removed */}
        {v.status === 'signedIn' && v.devices && v.devices.length > 0 && (
          <Box key="devices" flexDirection="column">
            <Text key="devices-title" color="inactive">Linked devices</Text>
            {v.devices.map(d => (
              <Box key={`device-${d.id}`} flexDirection="row" flexWrap="wrap" alignItems="center" columnGap={1}>
                {d.current
                  ? [<Text key="name">{`${deviceLabel(d)} · this device`}</Text>]
                  : [
                      <Text key="name">{`${deviceLabel(d)} · last seen ${d.lastSeenAt === undefined ? 'never' : agoText(d.lastSeenAt, clockNow)} ·`}</Text>,
                      <Button key={`sync-remove-${d.id}`}
                        label={v.confirmRemove === d.id ? `Press again to remove ${deviceLabel(d)} and its synced data` : 'Remove'}
                        variant={v.confirmRemove === d.id ? 'primary' : 'secondary'} dimColor={!!v.busy}
                        onPress={() => void removeDevice(syncIO($), d.id)} />,
                    ]}
              </Box>
            ))}
          </Box>
        )}
        {/* the page to sign in on, where the code is typed: as a link, and as text to copy */}
        {v.status === 'waiting' && v.url && (
          <Box flexDirection="column">
            {/* the link inside a Text, as the inline element it is; the address again as plain text to copy */}
            <Text>Open <Link href={v.url} label="the sign-in page" /> and enter the code {v.code ?? 'shown above'}.</Text>
            <Text dimColor>{v.url}</Text>
          </Box>
        )}
        {v.note && <Text dimColor>{v.note}</Text>}
      </Box>
    )
}

/**
 * The main pane's sync line: one quiet line, the rest in the settings pane. Signed out, a text button to turn
 * sync on; signing in, the code and the page (it's needed right there); signed in, when it last synced and a cog.
 */
function syncLine($: EngineInterface, els: Els, v: RangeSync, clockNow: number) {
  const { Box, Text, Button } = els
  if (v.status === 'off') return null
  if (v.status === 'waiting') return syncPanel($, els, v, clockNow)
  return (
    <Box key="sync" flexDirection="column" marginTop={1}>
      <Box flexDirection="row" flexWrap="wrap" justifyContent="space-between" alignItems="center" columnGap={1}>
        {v.status === 'signedIn'
          ? [
              <Box key="who" flexDirection="row" flexWrap="wrap" columnGap={1}>
                <Text color="claude">•</Text>
                <Text color="inactive">{`Synced across devices · last sync ${agoText(v.last, clockNow)}`}</Text>
              </Box>,
              <Button key="sync-settings" plain dimColor label="⚙ Settings" onPress={() => void openSyncPane($)} />,
            ]
          : [<Button key="sync-enable" plain label="Click here to enable sync between devices" dimColor
              onPress={() => void signIn(syncIO($))} />]}
      </Box>
      {v.note && <Text dimColor>{v.note}</Text>}
    </Box>
  )
}

/** Opens the pane, and asks for the device list if it wasn't asked for just now. */
async function openPane($: EngineInterface) {
  await $.ui.open({ id: PANE, title: TITLE })
  void refreshDevices(syncIO($), DEVICES_FRESH).catch(() => undefined)
}

/** What sync reaches through the engine: every call on `$` spelled here, in the hooks module. */
function syncIO($: EngineInterface): SyncIO {
  return {
    now: () => $.clock.now(),
    fetch: (url, init) => $.http.fetch(url, init),
    get: key => $.store.get(key),
    set: (key, value) => $.store.set(key, value),
    del: key => $.store.delete(key),
    keys: () => $.store.keys(),
    trafficOff: () => $.env.get('CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC'),
    hostName: () => hostName($),
    every: (ms, fn) => $.clock.every(ms, fn),
    after: (ms, fn) => $.clock.after(ms, fn),
    log: (text, options) => $.ui.log(text, options),
    view: () => read($, syncView),
    setView: async change => { await update($, syncView, change) },
    account: () => account,
    collect: () => collectLocal($),
    reload: () => loadAll($),
    peekDevice: () => peekDevice($),
  }
}

async function loadAll($: EngineInterface) {
  const now = await $.clock.now()
  const { lists, spans, stepLists } = await localLists($, now)
  // the other devices' lists, as synced: read beside this computer's, merging drops the repeats
  const far = await downloadedFor(syncIO($), account)
  lists.push(...(far.readings as RangeReading[][]))
  spans.push(...far.spans)
  stepLists.push(...(far.steps as RangeStep[][]))
  othersSeen = spans
  othersSteps = mergeSteps(stepLists, now)
  await update($, steps, () => mergeSteps([othersSteps, ownSteps], now))
  await update($, readings, () => merge(lists, now))
  await update($, seen, () => [...othersSeen, ...ownSeen])
}

/**
 * Notes that this session just got fresh figures (a response arrived), for telling
 * usage seen here from usage made elsewhere. Saved at most every 30 seconds.
 */
let seenSavedAt = 0
let seenShownAt = 0
async function watch($: EngineInterface) {
  const now = await $.clock.now()
  if (!ownKey) ownKey = newOwnKey(now)
  const before = ownSeen.length
  ownSeen = heartbeat(ownSeen, now)
  if (ownSeen.length !== before || now - seenSavedAt > 30_000) {
    seenSavedAt = now
    await $.store.set(seenKeyOf(ownKey), ownSeen)
  }
  // a redraw for a new span, else at most every 30 seconds: each response would redraw the pane otherwise
  if (ownSeen.length !== before || now - seenShownAt >= 30_000) {
    seenShownAt = now
    await update($, seen, () => [...othersSeen, ...ownSeen])
  }
}

/** Notes one response: its model, effort and weighted tokens. Saved at most every 30 seconds. */
let stepsSavedAt = 0
let stepsShownAt = 0
let stepsUnsaved = false
async function record($: EngineInterface, step: RangeStep) {
  const now = step[0]
  if (!ownKey) ownKey = newOwnKey(now)
  ownSteps = [...ownSteps.filter(s => s[0] >= now - KEEP), step]
  stepsUnsaved = true
  if (now - stepsSavedAt > 30_000) await saveSteps($, now)
  // the models card follows at most every 30 seconds, not on every response: the minute's loadAll catches up the rest
  if (now - stepsShownAt >= 30_000) {
    stepsShownAt = now
    await update($, steps, () => mergeSteps([othersSteps, ownSteps], now))
  }
}
async function saveSteps($: EngineInterface, now: number) {
  if (!stepsUnsaved || !ownKey) return
  stepsSavedAt = now
  stepsUnsaved = false
  await $.store.set(stepsKeyOf(ownKey), ownSteps)
}

/**
 * Keeps the daily totals and the self-check under the account (`<account>/days`, `<account>/check`): the
 * readings are kept 15 days, so the weekday profile's 8 weeks and the last 4 windows' self-check are kept
 * here, each built from the merged readings, the other devices' included. Saved only when they change.
 */
const daysKey = () => `${account}/days`
const checkKey = () => `${account}/check`
async function keepDays($: EngineInterface) {
  const now = await $.clock.now()
  const list = await read($, readings), watched = await read($, seen)
  const totals = dailyTotals(list, watched, now, ((await $.store.get(daysKey())) ?? []) as RangeDay[])
  const before = ((await $.store.get(checkKey())) ?? []) as RangeCheck[]
  const next = selfCheck(before, list, watched, totals, now)
  if (JSON.stringify(totals) !== JSON.stringify(await read($, days))) {
    await $.store.set(daysKey(), totals)
    await update($, days, () => totals)
  }
  if (JSON.stringify(next) !== JSON.stringify(before)) await $.store.set(checkKey(), next)
  if (JSON.stringify(next) !== JSON.stringify(await read($, check))) await update($, check, () => next)
}

async function capture($: EngineInterface, limits: readonly SessionRateLimit[]) {
  // figures from another account mean a sign-in since: read that account's record first
  if (await followAccount($)) await loadAll($)
  const now = await $.clock.now()
  const known = await read($, readings)
  const fresh: RangeReading[] = []
  for (const rl of limits) {
    const kind = rl.kind === 'five_hour' ? 0 : rl.kind === 'seven_day' ? 1 : -1
    if (kind === -1 || !rl.resetsAt) continue
    const resetsAt = Date.parse(rl.resetsAt)
    const r: RangeReading = [now, kind, rl.percentUsed, resetsAt]
    // this session's figures may be older than another's: only a new one is recorded
    const last = ofKind(known, kind === 0 ? 'five' : 'week').at(-1)
    if (!isStale(r, last) && (!last || last[2] !== r[2] || Math.abs(last[3] - r[3]) > 5 * MIN)) fresh.push(r)
  }
  if (fresh.length === 0) return
  if (!ownKey) ownKey = newOwnKey(now)
  own = merge([own, fresh], now)
  await $.store.set(ownKey, own)
  await update($, readings, list => merge([list, fresh], now))
}

/**
 * Reads the person's theme and derives the card's palettes from it. A custom
 * theme (`custom:<slug>`) is the person's own file or one a plugin ships.
 */
let themeFile: { slug: string; path: string } | undefined
async function loadTheme($: EngineInterface) {
  const setting = ((await $.settings.read()) as { theme?: unknown }).theme
  const dir = (await $.env.get('CLAUDE_CONFIG_DIR')) ?? `${await homeOf($)}/.claude`
  const theme = await resolveTheme(setting, async slug => {
    // found once, then read where it was; searched again only if it's gone
    if (themeFile?.slug === slug && await $.fs.exists(themeFile.path)) return await $.fs.read(themeFile.path)
    const own = `${dir}/themes/${slug}.json`
    if (await $.fs.exists(own)) { themeFile = { slug, path: own }; return await $.fs.read(own) }
    // plugins are cached as cache/<marketplace>/<plugin>/<version>/
    const cache = `${dir}/plugins/cache`
    for (const m of await $.fs.list(cache).catch(() => [])) {
      for (const pl of await $.fs.list(`${cache}/${m.name}`).catch(() => [])) {
        for (const ver of await $.fs.list(`${cache}/${m.name}/${pl.name}`).catch(() => [])) {
          const file = `${cache}/${m.name}/${pl.name}/${ver.name}/themes/${slug}.json`
          if (await $.fs.exists(file)) { themeFile = { slug, path: file }; return await $.fs.read(file) }
        }
      }
    }
    return undefined
  })
  const next = palettesFor(theme)
  if (JSON.stringify(next) !== JSON.stringify(await read($, palettes))) await update($, palettes, () => next)
}

async function models($: EngineInterface) {
  const list = await read($, readings)
  const watched = await read($, seen)
  const s = await read($, settings)
  const pal = await read($, palettes)
  await read($, tick)
  // the drawings' time, up to the next whole minute: a redraw with nothing new (a scroll, a response, the minute's tick)
  // then draws the very same drawings, which the surface keeps instead of loading them again (that flashed)
  const now = Math.ceil((await $.clock.now()) / MIN) * MIN
  const weekRecorded = recordedHours(list, 'week', now)
  const weekAvg = chosenAverage(s)
  // the 5-hour average runs from the window's opening: Anthropic's own figure, and the chart shows the whole window
  const fiveAvg: Average = { type: 'reset' }
  const stepList = await read($, steps)
  const learned = learn(list, stepList, watched, now)
  const projected = project(list, 'week', now, weekAvg, watched)
  // the bars follow the responses behind each rise, each weighed by its model's cost where that's known
  const shown = learned.models.filter(m => m.shown)
  const usual = shown.length ? shown.reduce((a, m) => a + m.w, 0) / shown.length : 1
  const weightOf = new Map(learned.models.map(m => [m.id, m.shown ? m.w : usual]))
  const work = stepList.map(st => [st[0], st[3] * (weightOf.get(st[1]) ?? usual)] as const)
  const shaped = (m: Model | null) => (m ? { ...m, increments: refine(m.increments, work) } : null)
  const week = shaped(projected)
  // 1.4's weekly projection: the last 7 whole days, today at no less than its expected use
  const totals = dailyTotals(list, watched, now, await read($, days))
  const plan = weekPlan(list, watched, totals, now, typicalMiss(await read($, check)))
  const five = shaped(project(list, 'five', now, fiveAvg, watched))
  // each limit's window by model and effort, each response weighed as the bars weigh it
  const weigh = (id: string) => weightOf.get(id) ?? usual
  const splits = {
    five: five ? usageSplit(five, list, stepList, watched, weigh, now) : null,
    week: projected ? usageSplit(projected, list, stepList, watched, weigh, now) : null,
  }
  return {
    now, s, weekRecorded, pal, week, plan, totals, five, splits,
    // how each limit's previous window ended, where the record can tell
    lastWeek: lastWindow(list, 'week', now, watched),
    lastFive: lastWindow(list, 'five', now, watched),
    learned,
    steps: stepList,
  }
}

async function choose($: EngineInterface, change: Partial<RangeSettings>) {
  await update($, settings, s => ({ ...s, ...change }))
  await $.store.set('settings', await read($, settings))
}

/** Sets the weekly window: any length, one that can't give an estimate yet saying so in the chart's place. */
async function setWindow($: EngineInterface, n: number, unit: 'h' | 'd') {
  await choose($, { mode: 'window', n: clampWindow(n, unit), unit })
}

export const register: Register = (on, options) => {
  configureSync(options.syncServer)

  on('session.start', async ($, e, next) => {
    account = ''
    await followAccount($)
    const saved = (await $.store.get('settings')) as RangeSettings | undefined
    // a saved "everything recorded" (now retired) becomes the custom window it sat beside
    if (saved) await update($, settings, () => ({ ...DEFAULT_SETTINGS, ...saved, mode: saved.mode === 'reset' ? 'reset' : 'window' }))
    await $.command.register({
      name: 'token-range',
      description: 'Token Range Monitor: open the pane, or set what the weekly average covers (/token-range 2d, /token-range 6h, /token-range reset)',
      argumentHint: '[window | reset]',
    })
    await startSync(syncIO($))
    await loadAll($)
    // a theme that can't be read leaves the card's default colours, never the rest of the start
    await loadTheme($).catch(() => undefined)
    await capture($, (await $.session.usage()).rateLimits)
    await keepDays($).catch(() => undefined)
    // the first sync waits for the session to be under way: nothing on the network holds up its start
    $.clock.after(1_000, () => void syncTick(syncIO($), true))
    // once a minute: pick up other sessions' readings and move "now" along; sync when it's due
    $.clock.every(60_000, async () => {
      await saveSteps($, await $.clock.now())
      const moved = await followAccount($)
      await loadAll($)
      await loadTheme($).catch(() => undefined)   // picks up a theme file edited in place
      await capture($, (await $.session.usage()).rateLimits)
      await keepDays($).catch(() => undefined)
      await update($, tick, n => n + 1)
      // another account's record syncs at once
      await syncTick(syncIO($), moved)
    })
    return next(e)
  })

  // at the end, the responses not yet saved are, and sync uploads once more
  on('session.end', async ($, e, next) => {
    try {
      await saveSteps($, await $.clock.now())
      await endSync(syncIO($))
    } catch { /* never in the way of the exit */ }
    return next(e)
  })

  // a turn's end and each tool call both follow a response, so the figures are fresh then;
  // the once-a-minute check above only re-reads the last response's figures, so it isn't watching
  on('session.measure', async ($, e, next) => {
    if (e.changed.includes('rateLimits')) await capture($, e.rateLimits)
    await watch($)
    return next(e)
  })

  // a theme switched from /theme, the menu or another plugin redraws the card at once
  on('config.set', { key: 'theme' }, async ($, e, next) => {
    const result = await next(e)
    await loadTheme($)
    return result
  }).catch(($, e, next) => next(e))   // never stands in the way of the theme change itself

  // every model response, main and subagents': its model, effort and tokens, for learning what each model costs
  on('turn.step', async function* ($, e, next) {
    const r = yield* next(e)
    try {
      if (r?.usage) await record($, [await $.clock.now(), r.usage.model || e.model, e.effort === undefined ? '' : String(e.effort), units(r.usage), e.agentId ? 1 : 0])
    } catch { /* never in the way of the response */ }
    return r
  })

  on('tool.call', async ($, e, next) => {
    await watch($)
    return next(e)
  })

  on('command.run', { command: 'token-range' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    await openPane($)
    if (!arg) return { text: 'Token Range Monitor opened.' }
    if (arg === 'reset' || arg === 'since reset') {
      await choose($, { mode: 'reset' })
      return { text: 'Weekly average now covers the time since the reset.' }
    }
    const w = parseWindow(arg)
    if (!w) return { text: `Couldn't read "${arg}". Use a window like 6h or 2d (at most 7d), or "reset".` }
    await setWindow($, w.unit === 'h' ? w.n : w.n * (w.unit === 'w' ? 7 : 1), w.unit === 'h' ? 'h' : 'd')
    // held to what's on offer: under 6 hours becomes 6
    const avg: Average = { type: 'hours', hours: windowHours(await read($, settings)) }
    return { text: `Weekly average now uses the last ${averageName(avg)}.` }
  })

  // C: one line above the prompt
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    const { plan, five, now } = await models($)
    if (!plan && !five) return next(e)
    const { Box, Text, Button } = $.ui.resolve(e)
    const partsOf = (short: boolean) => [
      ...(plan ? [{ key: 'week', part: weekPart(plan, short) }] : []),
      ...(five ? [{ key: 'five', part: fivePart(five, now, short) }] : []),
    ]
    // the full line where it fits, else the short one, so the band stays one line in a narrow column
    const short = partsWidth(partsOf(false).map(x => x.part)) > e.props.bodyColumns
    return (
      <Box flexDirection="row" flexWrap="wrap" columnGap={1} alignItems="center">
        {partsOf(short).flatMap(({ key, part: p }, i) => {
          return [
            ...(i ? [<Text key={`sep-${key}`} dimColor>·</Text>] : []),
            <Box key={`band-${key}`} flexDirection="row">
              <Text dimColor>{p.label} </Text>
              <Text bold dimColor={p.dim} color={p.dim ? undefined : p.spare ? 'success' : 'claude'}>{p.value}</Text>
              {p.rest && <Text dimColor>{p.rest}</Text>}
              {p.tag && <Text key={`tag-${key}`} dimColor>{` ${p.tag}`}</Text>}
            </Box>,
          ]
        })}
        <Button key="details" label="Details ↗" onPress={() => void openPane($)} />
      </Box>
    )
  })

  // the sync settings: their own pane, opened from the main pane's cog
  on('ui.render', { component: 'Pane', requestId: SYNC_PANE }, async ($, e) => {
    const els = $.ui.resolve(e)
    const { Box, Text } = els
    const v = await read($, syncView)
    return (
      <Box flexDirection="column" gap={1}>
        <Text bold>Sync across devices</Text>
        <Text dimColor>Your usage history, shared between the computers you sign in on. Usage figures only: never prompts or code.</Text>
        {syncPanel($, els, v, await $.clock.now())}
      </Box>
    )
  })

  // B: the side pane
  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { now, s, week, five, pal, lastWeek, lastFive, weekRecorded, learned, plan, totals, splits } = await models($)
    const els = $.ui.resolve(e)
    const { Box, Text, Button } = els
    const sync = await read($, syncView)
    // the real time for the sync row's texts: `now` is the drawings', rounded up to the minute
    const clockNow = await $.clock.now()
    // the terminal draws no Svg: there the cards are text
    const Svg = e.surface !== 'terminal' && 'Svg' in els ? els.Svg : null
    // the drawings are laid out at the card's inner width; the 1.3 charts' heights follow it
    const size = fit(e.props.bodyColumns)
    const W = size.width
    const lastOf = (m: Model) => (m.kind === 'week' ? lastWeek : lastFive)
    const open = await read($, details)
    const toggle = (key: string) => void update($, details, l => (l.includes(key) ? l.filter(k => k !== key) : [...l, key]))
    // the head's figures in words, for a drawing's alt text
    const figuresText = (m: Model) =>
      `At reset ${leftText(m)}, your pace ${m.noData ? 'no data' : rateText(m, m.rate)}, safe pace ${rateText(m, m.limit)}.${paceText(m) ? ` ${paceText(m)}` : ''}`
    const lastAlt = (last: LastWindow | null) => (last ? `${LAST_LABEL} ${lastWindowText(last)}. ${lastWindowNote(last)} ` : '')
    const gap = Svg ? 1 : 0

    // every drawing a plain image, never interactive: the surface loads an interactive drawing (a sandboxed frame)
    // again on every redraw, a scroll's too, and that flashed. A plain function, not a component, each drawing keyed;
    // its height left out, so it follows the drawing's proportions at whatever width it's shown
    const draw = (key: string, svg: string, alt: string, layout = W) =>
      Svg ? <Svg key={key} source={asImage(svg, layout)} alt={alt} /> : null

    // the window selector: native widgets, so hover, focus and clicks are the surface's own
    const unit = s.unit === 'h' ? 'h' : 'd'
    const n = clampWindow(s.n, unit)
    const isCustom = s.mode === 'window'
    const seg = (key: string, label: string, isOn: boolean, onPress: () => void, off = false) => (
      <Button key={key} label={label} variant={isOn && !off ? 'primary' : 'secondary'} dimColor={!isOn || off} onPress={() => { if (!off) onPress() }} />
    )
    // until there's enough recorded for a weekly average, there's nothing to choose between: the choices dim and do nothing
    const choicesOff = weekRecorded < MIN_RECORDED_H.week
    const modeButtons = (
      <Box key="mode" flexDirection="row" flexWrap="wrap" alignItems="center" columnGap={1} rowGap={gap}>
        {seg('mode-reset', 'Since reset', s.mode === 'reset', () => void choose($, { mode: 'reset' }), choicesOff)}
        {seg('mode-custom', 'Custom', isCustom, () => void setWindow($, n, unit), choicesOff)}
      </Box>
    )
    const windowRow = isCustom && !choicesOff ? (
      <Box key="window" flexDirection="row" flexWrap="wrap" alignItems="center" columnGap={1} rowGap={gap}>
        <Text color="inactive">Last</Text>
        <Button key="win-dec" label="−" dimColor={n <= UNIT_MIN[unit]} onPress={() => void setWindow($, n - 1, unit)} />
        <Text bold color="text">{` ${n} `}</Text>
        <Button key="win-inc" label="+" dimColor={n >= UNIT_MAX[unit]} onPress={() => void setWindow($, n + 1, unit)} />
        {seg('unit-h', 'hours', unit === 'h', () => void setWindow($, n, 'h'))}
        {seg('unit-d', 'days', unit === 'd', () => void setWindow($, n, 'd'))}
      </Box>
    ) : null

    // the models card: where this window's use went, by model and effort, for the limit that's tighter unless one is picked
    const base = baselineOf(learned, s.baseline)
    const shown = learned.models.filter(m => m.shown)
    const names = shortNames(shown)
    const tightness = (k: 'five' | 'week') => k === 'five'
      ? (five ? (five.over ? -1 : five.arrive) : Infinity)
      : (plan ? (plan.pct >= 100 || plan.runsOutAt !== null ? -1 : plan.left) : Infinity)
    const picked = open.includes('models-period:five') ? 'five' : open.includes('models-period:week') ? 'week' : null
    const period: 'five' | 'week' = picked ?? (tightness('five') < tightness('week') ? 'five' : 'week')
    const split: UsageSplit | null = splits[period] ?? splits[period === 'five' ? 'week' : 'five']
    const pickPeriod = (k: 'five' | 'week') => void update($, details, l => [...l.filter(x => !x.startsWith('models-period:')), `models-period:${k}`])
    const periodButtons = (
      <Box key="models-period" flexDirection="row" flexWrap="wrap" alignItems="center" columnGap={1} rowGap={gap}>
        {seg('period-five', '5h', split?.kind === 'five', () => pickPeriod('five'), !splits.five)}
        {seg('period-week', 'Week', split?.kind === 'week', () => pickPeriod('week'), !splits.week)}
      </Box>
    )
    const modelsOpen = open.includes('models')
    const modelsSummary = !split ? 'No limit reported yet.'
      : split.models.length ? split.models.slice(0, 3).map(m => `${names.get(m.id) ?? m.name} ${one(m.pct)}%`).join(' · ')
      : 'Nothing used yet this window.'
    // what the card counts, three plain lines, each point first
    const modelsInfo = (
      <Box key="models-info" flexDirection="column">
        {MODELS_INFO.map(([point, rest], i) => (
          <Box key={`info-${i}`} flexDirection="row" flexWrap="wrap" columnGap={1}>
            <Text bold dimColor>{point}</Text>
            <Text dimColor>{rest}</Text>
          </Box>
        ))}
      </Box>
    )
    // the costs as a small table: name, figure, where the figure comes from
    const rowsOfCost = costRows(learned, base)
    const costTable = (
      <Box key="models-costs" flexDirection="column">
        <Text dimColor>{rowsOfCost.length ? 'Token cost, per token' : 'Costs compare once two models have been used.'}</Text>
        {rowsOfCost.map(r => (
          <Box key={`cost-${r.id}`} flexDirection="row" columnGap={2}>
            <Box width={12} flexShrink={0}><Text>{r.name}</Text></Box>
            <Box width={7} flexShrink={0}><Text bold>{r.x}</Text></Box>
            <Text dimColor>{r.note}</Text>
          </Box>
        ))}
      </Box>
    )
    const compareRow = base && (
      <Box key="compare" flexDirection="row" flexWrap="wrap" justifyContent="flex-end" alignItems="center" columnGap={1} rowGap={gap}>
        <Text color="inactive">Compare with</Text>
        {shown.map(m => seg(`base-${m.id}`, names.get(m.id) ?? m.name, m === base, () => void choose($, { baseline: m.id })))}
      </Box>
    )

    // sync: one quiet line here; everything else is in its own pane, opened from the cog
    const syncRow = (v: RangeSync) => syncLine($, els, v, clockNow)

    if (!week && !five) {
      return (
        <Box flexDirection="column" gap={1}>
          <Text>No usage limits reported yet.</Text>
          <Text dimColor>They arrive with Claude's next response, on a Pro or Max subscription.</Text>
          {syncRow(sync)}
        </Box>
      )
    }


    if (Svg) {
      // ---- the desktop: the design's cards, each a drawing with the pane's own controls in it ----
      const runsText = (key: string, runs: Run[]) => (
        <Box key={key} flexDirection="row" flexWrap="wrap" flexShrink={1}>
          {runs.map((r, i) => (
            <Text key={`${key}-${i}`} color={r.fill === C.bad ? 'claude' : r.fill === C.good ? 'success' : 'inactive'}>{r.s}</Text>
          ))}
        </Box>
      )
      /**
       * One card: its drawing and controls on the card, then the strip under it (what it says while closed, and
       * Details), then what Details opens, on the strip's tone.
       */
      const card = (key: string, body: Array<JSX.Element | null | false | undefined>, strip?: { summary: JSX.Element; detailsKey: string; inner: () => Array<JSX.Element | null | false | undefined> }) => {
        const isOpen = !!strip && open.includes(strip.detailsKey)
        return (
          <Box key={`block-${key}`} flexDirection="column" marginBottom={1} borderStyle="round" borderColor="userMessageBackground" backgroundColor="userMessageBackground">
            <Box key={`inner-${key}`} flexDirection="column" paddingX={2} paddingY={1} gap={1}>{body}</Box>
            {strip && (
              <Box key={`strip-${key}`} flexDirection="row" flexWrap="wrap" justifyContent="space-between" alignItems="center" columnGap={2} paddingX={2} paddingY={1} backgroundColor={INSET}>
                {strip.summary}
                <Button key={`details-btn-${strip.detailsKey}`} plain dimColor={!isOpen} label={isOpen ? 'Hide details ▴' : 'Details ▾'} onPress={() => toggle(strip.detailsKey)} />
              </Box>
            )}
            {strip && isOpen && (
              <Box key={`details-${key}`} flexDirection="column" paddingX={2} paddingBottom={1} gap={1} backgroundColor={INSET}>{strip.inner()}</Box>
            )}
          </Box>
        )
      }
      // 1.3's card for a limit, behind its Details: its figures, its chart, what the average covers, Last window
      const oldInner = (m: Model, title: string, controls: JSX.Element | null, extra: JSX.Element | null) => {
        const last = lastOf(m)
        const empty = emptyChartText(m, now)
        const chart = empty ? emptyChartSvg(m, now, W, historyPalettes(pal))
          : m.kind === 'week' ? weekChart(m, now, W, historyPalettes(pal), size.weekHeight) : fiveChart(m, now, W, historyPalettes(pal), size.fiveHeight)
        return [
          draw(`head-${m.kind}`, oldFigures(m, last, W, pal),
            `${title}. ${resetsIn(m)}. ${isShort(m) ? `${runsOut(m)}. ` : ''}${figuresText(m)} ${lastAlt(last)}`),
          draw(`chart-${m.kind}`, chart, empty ? empty.join('. ') : `${averageNote(m)} Your pace ${rateText(m, m.rate)}, safe pace ${rateText(m, m.limit)}.`),
          <Box key={`old-foot-${m.kind}`} flexDirection="row" flexWrap="wrap" justifyContent="space-between" alignItems="center" columnGap={2} rowGap={gap}>
            <Text key={`note-${m.kind}`} color="inactive">{empty || m.kind === 'five' ? '' : averageNote(m)}</Text>
            {controls}
          </Box>,
          extra,
          ...(last ? [LAST_INFO, lastWindowNote(last)] : []).map((para, i) => <Text key={`details-${m.kind}-${i}`} dimColor>{para}</Text>),
        ]
      }

      /**
       * How tightly the cards are drawn, so they all fit the pane's height where they can: 0 as designed, 1 without
       * the masthead (the pane's title names it), 2 with the cards' headers and headlines smaller too. At each level
       * the weekly card's day columns give up what the rest overruns, down to DAYS_MIN, so the cards fill the
       * pane rather than leave a step's worth empty under them. Each level's drawings are measured; the native parts
       * (padding, gaps, strips, the sync line) are counted in rows, at FIT_PX's sizes: an estimate, so a little may
       * still scroll, and a pane too short even for the densest scrolls.
       */
      const showsWeek = !!(plan && week), showsTodayCard = !!(plan && week && showsToday(plan))
      const weekSvg = (dense: boolean, shrink = 0) => weekCardSvg(plan!, pastDays(plan!), W, pal, dense, shrink)
      const todayDrawing = (dense: boolean) => todaySvg(plan!, W, pal, dense)
      const fiveSvg = (dense: boolean) => fiveCardSvg(five!, now, W, pal, dense)
      const headOfModels = (dense: boolean) => modelsHead(split, W, pal, dense)
      const usageSvg = split ? modelsUsage(split, W, pal) : null
      const legendShown = showsWeek && !plan!.noData && plan!.pct < 100
      const heightAt = (level: number) => {
        const dense = level >= 2
        const drawn = [
          level === 0 ? mastheadSvg(W, pal) : null,
          showsWeek ? weekSvg(dense) : null,
          legendShown ? weekLegendSvg(plan!.basis === 'early', pal).svg : null,
          showsTodayCard ? todayDrawing(dense) : null,
          five ? fiveSvg(dense) : null,
          headOfModels(dense),
          usageSvg,
        ].reduce((a, svg) => a + (svg ? drawingHeight(svg) : 0), 0)
        // a card: its padding, the gaps between what's in it, its margin; a strip under it adds its padding and button
        const cardRows = (items: number, strip: boolean) => 2 + Math.max(0, items - 1) + 1 + (strip ? 3 : 0)
        const rows = (level === 0 ? 1 : 0)
          + (showsWeek ? cardRows(legendShown ? 2 : 1, true) : 1)
          + (showsTodayCard ? cardRows(1, false) : 0)
          + (five ? cardRows(1, true) : 1)
          + cardRows(split ? 3 : 2, true)
          + 2
          // an open Details: its text and drawings, roughly
          + ['week', 'five', 'models'].filter(k => open.includes(k)).length * 18
        return drawn + rows * FIT_PX.native
      }
      const room = Math.max(0, (e.props.scroll?.bodyRows ?? 0) * FIT_PX.row - FIT_PX.spare)
      // what the day columns give up at a level, past which that level doesn't fit
      const giveUp = (l: number) => Math.max(0, heightAt(l) - room)
      const slack = legendShown ? daysHeight(W) - DAYS_MIN : 0
      const level = !room ? 0 : [0, 1].find(l => giveUp(l) <= slack) ?? 2
      const dense = level >= 2
      const shrink = room && legendShown ? giveUp(level) : 0

      const weekCard = plan && week ? (() => {
        const past = pastDays(plan), hd = weekHead(plan), L = weekBarLabels(plan)
        const alt = `This week, 100% = your weekly limit. ${hd.head}. ${hd.sub} ${plan.noData ? '' : `${[L.used, L.add].filter(Boolean).join(', ')}. ${daysText(plan, past)}.`}`
        const chart = !plan.noData && plan.pct < 100
        const legend = weekLegendSvg(plan.basis === 'early', pal)
        return card('week', [
          draw('week-card', weekSvg(dense, shrink), alt),
          chart && (
            <Box key="week-legend-row" flexDirection="row" flexWrap="wrap" alignItems="center" columnGap={2}>
              {draw('week-legend', legend.svg, plan.basis === 'early' ? 'Solid: used. Outlined: not known yet.' : 'Solid: used. Striped: expected at your pace.', legend.width)}
            </Box>
          ),
        ], {
          detailsKey: 'week',
          summary: <Box key="summary-week" />,
          inner: () => oldInner(week, 'This week', modeButtons, windowRow),
        })
      })() : <Text key="no-week" dimColor>No weekly limit reported.</Text>

      // today, in today's budget: a card of its own under the week's
      const todayCard = plan && week && showsToday(plan)
        ? card('today', [draw('today-card', todayDrawing(dense), (() => { const d = todayText(plan); return `Today, 100% = today's budget. ${d.predicted}. ${d.note}` })())])
        : null

      const fiveCard = five ? card('five', [
        draw('five-card', fiveSvg(dense), (() => { const hd = fiveHead(five, now); return `5-hour window, 100% = your 5-hour limit. ${hd.head}. ${hd.sub}` })()),
      ], {
        detailsKey: 'five',
        summary: <Box key="summary-five" />,
        inner: () => oldInner(five, '5-hour window', null, null),
      }) : <Text key="no-five" dimColor>No current 5-hour window seen: it shows after your next response.</Text>

      const modelsCard = card('models', [
        draw('models-head', headOfModels(dense), `Models: where your usage went. ${modelsSummary}`),
        periodButtons,
        split && usageSvg ? draw('models-usage', usageSvg, splitText(split)) : null,
      ], {
        detailsKey: 'models',
        summary: <Box key="summary-models" />,
        inner: () => [
          costTable,
          compareRow,
          modelsInfo,
        ],
      })

      return (
        <Box key="cards" flexDirection="column" gap={1}>
          {level === 0 && draw('masthead', mastheadSvg(W, pal), 'Token Range Monitor. Track your usage, limits, and the time you have left.')}
          <Box key="pane" flexDirection="column">
            {weekCard}
            {todayCard}
            {fiveCard}
            {modelsCard}
            {syncRow(sync)}
          </Box>
        </Box>
      )
    }

    // ---- the terminal: the same cards as text, each with its bars ----
    const cardBox = { gap: 0, marginBottom: 0, paddingX: 1 }
    // the card's inner width: the pane's, less the border and a column of padding each side
    const inner = Math.max(20, e.props.bodyColumns - 4)
    /**
     * A bar on a card's scale, 100% at its right end: what's used solid with its figure in it, shaded to where this
     * pace ends up with that total in it (in red past 100%), the rest faint. A figure its part can't hold is left out
     * of the bar and comes back, so the line under it can say it.
     */
    const hbar = (key: string, used: number, total: number | null) => {
      const n = inner, clamp = (v: number) => Math.max(0, Math.min(1, v / 100))
      const u = Math.round(n * clamp(used)), t = total === null ? u : Math.max(u, Math.round(n * clamp(total)))
      const over = (total ?? 0) > 100
      // a label centred in a run of `w` cells, padded with `fill`; null when it doesn't fit with a cell either side
      const centred = (label: string, w: number, fill: string) => {
        if (w < label.length + 2) return null
        const l = Math.floor((w - label.length) / 2)
        return fill.repeat(l) + label + fill.repeat(w - l - label.length)
      }
      const usedLabel = `${one(used)}%`, totalLabel = total === null ? null : `~${one(total)}%`
      const solid = centred(usedLabel, u, ' ')
      const shade = totalLabel === null ? '▒'.repeat(t - u) : centred(` ${totalLabel} `, t - u, '▒')
      const missing = [...(solid === null ? [`${usedLabel} used`] : []), ...(totalLabel !== null && shade === null ? [`${totalLabel} by the reset`] : [])]
      return {
        bar: (
          <Box key={key} flexDirection="row">
            <Text color="inverseText" backgroundColor="claude" bold>{solid ?? ' '.repeat(u)}</Text>
            <Text color={over ? 'error' : 'claude'} bold={over}>{shade ?? '▒'.repeat(t - u)}</Text>
            <Text color="subtle">{'░'.repeat(n - t)}</Text>
          </Box>
        ),
        missing,
      }
    }
    /** The line under a bar: what the bar couldn't hold on the left, when it resets on the right. */
    const barFoot = (key: string, missing: string[], right: string) => (
      <Box key={key} flexDirection="row" flexWrap="wrap" justifyContent="space-between" columnGap={2}>
        <Text dimColor>{missing.join(' · ')}</Text>
        <Text dimColor>{right}</Text>
      </Box>
    )
    /** A card's title, and its headline on the right: only the figure in it (a %, or a time) in colour. */
    const titleRow = (key: string, title: string, head: string, tone: 'good' | 'bad' | 'dim') => (
      <Box key={key} flexDirection="row" flexWrap="wrap" justifyContent="space-between" columnGap={2}>
        <Text bold>{title}</Text>
        <Box flexDirection="row">
          {head.split(/(~?\d+(?:\.\d+)?%|~\d\d:\d\d)/).filter(Boolean).map((part, i) => (
            <Text key={`h${i}`} bold dimColor={tone === 'dim'} color={tone !== 'dim' && /^~?\d/.test(part) ? (tone === 'bad' ? 'error' : 'claude') : undefined}>{part}</Text>
          ))}
        </Box>
      </Box>
    )
    /**
     * The days of this window as columns, in % of the weekly limit: each day's figure over its column and its
     * name under it, past days and today solid, the days to come dim at this pace.
     */
    const dayColumns = (p: WeekPlan, rows: number) => {
      const early = p.basis === 'early'
      const days = [
        ...pastDays(p).map((v, i) => ({ name: dayName(p.days[i]!.start), v, label: `${one(v)}%`, later: false, today: false })),
        { name: dayName(p.dayStart), v: p.usedToday, label: `${one(p.usedToday)}%`, later: false, today: true },
        ...p.later.map(d => ({ name: dayName(d.start), v: early ? 0 : d.amount, label: early ? '?' : `~${one(d.amount)}%`, later: true, today: false })),
      ]
      const colW = Math.max(6, Math.min(9, Math.floor(inner / days.length)))
      const top = Math.max(1, ...days.map(d => d.v))
      const glyph = (v: number, row: number) => {
        const eighths = Math.round(v / top * rows * 8) - row * 8
        return eighths >= 8 ? '█' : eighths <= 0 ? ' ' : ' ▁▂▃▄▅▆▇'[eighths]!
      }
      const cell = (k: string, text: string, props: Record<string, unknown>) => (
        <Box key={k} width={colW} flexShrink={0}><Text {...props}>{text}</Text></Box>
      )
      return (
        <Box key="week-days" flexDirection="column">
          <Box flexDirection="row">{days.map((d, i) => cell(`v${i}`, d.label, { dimColor: true }))}</Box>
          {Array.from({ length: rows }, (_, r) => rows - 1 - r).map(row => (
            <Box key={`r${row}`} flexDirection="row">
              {days.map((d, i) => cell(`b${row}-${i}`, glyph(d.v, row).repeat(Math.min(4, colW - 2)), { color: 'claude', dimColor: d.later }))}
            </Box>
          ))}
          <Box flexDirection="row">{days.map((d, i) => cell(`n${i}`, d.today ? `${d.name}•` : d.name, d.today ? { color: 'claude', bold: true } : { dimColor: true }))}</Box>
        </Box>
      )
    }
    const termCard = (key: string, children: Array<JSX.Element | null | false>) => (
      <Box key={`block-${key}`} flexDirection="column" {...cardBox} borderStyle="round" borderColor="userMessageBackground" backgroundColor="userMessageBackground">{children}</Box>
    )
    /**
     * The days' columns' rows of bars, so the cards fit the pane's rows where they can: 3, or 1 in a short pane, or
     * none (0) in one shorter still. The rest is counted: each card's border, its lines, the sync line.
     */
    const dayRows = (() => {
      const room = e.props.scroll?.bodyRows ?? 0
      if (!room) return 3
      const weekRows = plan ? 2 + 1 + (plan.noData ? 0 : 2) : 1
      const todayRows = plan && showsToday(plan) ? 4 : 0
      const fiveRows = five ? 2 + 1 + (five.noData ? 0 : 2) : 1
      const modelsRows = 2 + 2 + (split ? 1 + split.models.length + (split.notRecorded >= 0.05 ? 1 : 0) : 0) + (modelsOpen ? 3 + rowsOfCost.length + MODELS_INFO.length + 2 : 0)
      const rest = weekRows + todayRows + fiveRows + modelsRows + 2
      const columns = plan && !plan.noData && plan.pct < 100
      if (!columns) return 3
      return [3, 1].find(r => rest + 2 + r <= room) ?? 0
    })()
    // the weekly card: its headline, the week as a bar, its days as columns
    const weekCardTerm = (p: WeekPlan) => {
      const hd = weekHeadline(p), L = weekBarLabels(p)
      const bar = p.noData ? null : hbar('week-bar', p.pct, L.add === null ? null : p.pct + toCome(p))
      return termCard('week', [
        titleRow('week-title', 'This week', hd.badge ? `${hd.head} ${hd.badge}` : hd.head, hd.tone),
        bar && bar.bar,
        bar && barFoot('week-foot', bar.missing, `resets ${dayTime(p.resetsAt)}`),
        !p.noData && p.pct < 100 && dayRows > 0 && dayColumns(p, dayRows),
      ])
    }
    // today against its budget, laid out as the 5-hour card
    const todayCardTerm = (p: WeekPlan) => {
      const at = overBudgetAt(p)
      const head = at === null ? 'Within budget' : at <= p.now ? 'Over budget' : `Over budget ~${hm(at)}`
      const bar = hbar('today-bar', p.usedOfBudget, p.predicted > p.usedOfBudget + 0.05 ? p.predicted : null)
      return termCard('today', [
        titleRow('today-title', 'Today', head, at === null ? 'good' : 'bad'),
        bar.bar,
        bar.missing.length ? barFoot('today-foot', bar.missing, '') : null,
      ])
    }
    // the 5-hour card: its headline, then the window's use as a bar
    const fiveCardTerm = (m: Model) => {
      const hd = fiveHead(m, now), proj = 100 - m.arrive, cut = m.noData ? null : cutOff(m, now)
      const bar = m.noData ? null : hbar('five-bar', m.pct, proj > m.pct ? proj : null)
      // the short headline: the reset's time is under the bar
      const head = m.noData || m.pct >= 100 ? hd.head : cut !== null ? `Cut off ~${hm(cut)}` : 'Lasts to the reset'
      return termCard('five', [
        titleRow('five-title', '5-hour window', head, hd.tone),
        bar && bar.bar,
        bar && barFoot('five-foot', bar.missing, `resets ${hm(m.resetsAt)}`),
      ])
    }
    const detailsButton = (key: string) => (
      <Button key={`details-btn-${key}`} plain dimColor label={open.includes(key) ? 'Hide details' : 'Details'} onPress={() => toggle(key)} />
    )
    // the models card: the split as one bar of each model's share, a line per model under it, the costs behind Details
    const modelBar = (sp: UsageSplit) => {
      const n = inner, colour = (f: string) => (f === 'fable' ? 'claude' : f === 'opus' ? 'claude' : f === 'sonnet' ? 'suggestion' : 'inactive')
      let used = 0
      const segsOf = sp.models.map((m, i) => {
        const c = Math.round(n * m.pct / 100)
        used += c
        return <Text key={`mb-${i}`} color={colour(m.family)} dimColor={i % 2 === 1}>{(i % 2 ? '▓' : '█').repeat(c)}</Text>
      })
      const nr = Math.min(n - used, Math.round(n * sp.notRecorded / 100))
      return (
        <Box key="models-bar" flexDirection="row">
          {segsOf}
          <Text color="subtle">{'▒'.repeat(Math.max(0, nr))}</Text>
          <Text color="subtle">{'░'.repeat(Math.max(0, n - used - nr))}</Text>
        </Box>
      )
    }
    const modelsCard = (
      <Box key="block-models" flexDirection="column" {...cardBox} borderStyle="round" borderColor="userMessageBackground" backgroundColor="userMessageBackground">
        <Box key="models-title" flexDirection="row" flexWrap="wrap" justifyContent="space-between" columnGap={2}>
          <Text bold>Models</Text>
          {periodButtons}
        </Box>
        {split && modelBar(split)}
        {split && split.models.map(m => (
          <Box key={`ml-${m.id}`} flexDirection="row" justifyContent="space-between" columnGap={2}>
            <Text>{(() => { const ef = shownEffort(m); return `${m.name}${ef.length > 1 || (ef[0] && ef[0][0] !== 'default') ? `  ${ef.map(([e, v]) => `${e} ${one(v)}%`).join(' · ')}` : ''}` })()}</Text>
            <Text bold>{`${one(m.pct)}%`}</Text>
          </Box>
        ))}
        {split && split.notRecorded >= 0.05 && (
          <Box key="ml-nr" flexDirection="row" justifyContent="space-between" columnGap={2}>
            <Text dimColor>Not recorded</Text>
            <Text dimColor>{`${one(split.notRecorded)}%`}</Text>
          </Box>
        )}
        <Box key="models-foot" flexDirection="row" justifyContent="flex-end">{detailsButton('models')}</Box>
        {modelsOpen && costTable}
        {modelsOpen && modelsInfo}
        {modelsOpen && compareRow}
      </Box>
    )

    return (
      <Box key="cards" flexDirection="column">
        {plan ? weekCardTerm(plan) : <Text dimColor>No weekly limit reported.</Text>}
        {plan && showsToday(plan) && todayCardTerm(plan)}
        {five ? fiveCardTerm(five) : <Text dimColor>No current 5-hour window seen: it shows after your next response.</Text>}
        {modelsCard}
        {syncRow(sync)}
      </Box>
    )
  })
}

